window.RP_SESSION={"id":"S-153282094fed","messages":[{"id":"RP-III-0100094","time":"2026-05-16T01:05:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"야심한 새벽의 길드 로비에는, 머리에 나이트캡을 뒤집어 쓴 잠옷 차림의 니콜라스가 앉아 있습니다. 저런 옷으로 기숙사 밖까지 나오다니 무슨 생각인걸까요!\n\n늘 커피가 담겨있던 잔에는 캐모마일 차가 그 자리를 대신하고 있었습니다. 하지만 그럼에도 덜덜 떨리는 다리는 여전하고···.\n\n무표정한 얼굴은 멍하다기보다도 불만이 많아보입니다.","characters":["P-216ccc194078"]},{"id":"RP-III-0100095","time":"2026-05-16T01:22:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"야심한 새벽. 우울해 보이는 니콜라스에게 다가가는건 역시 새하얀 늑대 한 마리 뿐.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100096","time":"2026-05-16T01:22:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 니콜라스의 발치에 드러눕는다.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100097","time":"2026-05-16T01:24:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"발등 위로 린의 온기가 전해집니다. 발 위에 카펫을 올려다 둔 느낌!\n\n···하지만 여전히 잠은 안 와요.","characters":["P-216ccc194078"]},{"id":"RP-III-0100098","time":"2026-05-16T01:25:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잠이 오지 않아도 괜찮습니다. 새하얀 털뭉치가 니콜라스 옆에 드러누워 기분 좋은 숨소리를 내고 있거든요.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100099","time":"2026-05-16T01:25:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100100","time":"2026-05-16T01:26:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 4 = 4\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0100101","time":"2026-05-16T01:26:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 그닥 니콜라스를 바라고 온건 아닌 것 같군요.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100102","time":"2026-05-16T01:26:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"육포 같은거 없나요?","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100103","time":"2026-05-16T01:27:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"누가 잠옷에 육포를 넣어가지고 다닙니까","characters":["P-216ccc194078"]},{"id":"RP-III-0100104","time":"2026-05-16T01:28:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린이 플린트의 발등을 핥습니다. 쓰다듬이라도 내놓으라는 뜻일까요.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100105","time":"2026-05-16T01:31:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"린의 혀가 닿는 감촉에 놀라 반사적으로 다리를 들썩입니다. 무릎을 책상 밑에 찧고 말았습니다! 멍이 하나 더 생기겠군요.\n\n린을 한참동안 바라봅니다. 뭘 원하는건지 모르는 눈치.","characters":["P-216ccc194078"]},{"id":"RP-III-0100106","time":"2026-05-16T01:31:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-216ccc194078"]},{"id":"RP-III-0100107","time":"2026-05-16T01:31:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'니콜라스 플린트'의 지능 판정 :\n[12] + [2] = [14]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-III-0100108","time":"2026-05-16T01:33:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"바보.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100109","time":"2026-05-16T01:33:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"바보 아니네","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100110","time":"2026-05-16T01:34:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"그제야 린의 의도를 조금이나마 깨닫고는, 조금 어색하게 손을 가져다 댑니다.","characters":["P-216ccc194078"]},{"id":"RP-III-0100111","time":"2026-05-16T01:34:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 쓰다듬을 받으며 뒹굴고 배 까고 헥헥거리며 실컷 그 느낌을 즐깁니다.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100112","time":"2026-05-16T01:34:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"헥헥헥헥헥","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100113","time":"2026-05-16T01:37:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"미련하다.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0100114","time":"2026-05-16T01:38:00+09:00","room":"RP III","name":"린(엘타리온의 동료)","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"린은 니콜라스가 무슨 소리를 하건 신경도 쓰지 않고 헥헥거리며 몸을 이리저리 움직이며 꼬리를 마구 붕방방 흔든다.","characters":["P-cf90597a7c66"]},{"id":"RP-III-0100115","time":"2026-05-16T02:06:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-216ccc194078"]},{"id":"RP-III-0100116","time":"2026-05-16T02:06:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
